import{c as t,Q as a,j as n,m as s}from"./chunks/framework.BqPkuuVc.js";const o="/assets/commentary-relay-feed.CI_RQ3Je.png",r="/assets/commentary-relay-class-complete.mggWG2Ga.png",p=JSON.parse('{"title":"Commentary","description":"","frontmatter":{},"headers":[],"relativePath":"user/screens/commentary.md","filePath":"user/screens/commentary.md"}'),i={name:"user/screens/commentary.md"};function h(l,e,g,c,d,m){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="commentary" tabindex="-1">Commentary <a class="header-anchor" href="#commentary" aria-label="Permalink to &quot;Commentary&quot;">​</a></h1><p><strong>Audience:</strong> Commentators and event narrators.</p><p>The <strong>Commentary</strong> view is a live feed of everything happening in the event — starts, radio-control punches, finishes, and whole classes wrapping up — written in plain language with the placing context an announcer needs. It&#39;s designed to sit on a screen in front of the commentary box and give you a running story to talk to.</p><h2 id="opening-commentary" tabindex="-1">Opening Commentary <a class="header-anchor" href="#opening-commentary" aria-label="Permalink to &quot;Opening Commentary&quot;">​</a></h2><p>On the <strong>Screens</strong> page, in the <strong>Commentary</strong> section, click <strong>Open</strong> — the feed opens in a new browser tab. The main feed runs down the middle, with the <strong>Classes</strong> panel on its left and, on its right, a panel listing every item whatever the filters say.</p><p>The Commentary view is its own web page (URL <code>/commentary/&lt;event-id&gt;</code>), so you can open it on a second machine the same way you&#39;d open an <a href="./creating-screens">arena screen</a>: point that device&#39;s browser at the URL. Any commentary view that&#39;s currently open is listed in the Commentary section so you can see what&#39;s connected.</p><h2 id="what-the-feed-shows" tabindex="-1">What the feed shows <a class="header-anchor" href="#what-the-feed-shows" aria-label="Permalink to &quot;What the feed shows&quot;">​</a></h2><p>Each item is timestamped and tagged by type — <strong>start</strong>, <strong>radio</strong>, <strong>finish</strong>, <strong>status</strong> (e.g. a DNF), or <strong>Class Complete</strong> when a class finishes. Items carry the competitor&#39;s name and class, the placing context (for example moving into the lead, or where a finisher slots in), and a medal (🥇🥈🥉) for the podium or a status chip for non-finishers. The newest items animate in at the top, so the feed reads as a live narrative.</p><h2 id="relays" tabindex="-1">Relays <a class="header-anchor" href="#relays" aria-label="Permalink to &quot;Relays&quot;">​</a></h2><p>In a relay class the feed follows the <strong>teams</strong>, not the runners. Each item names the team first, with the leg and the runner on the line underneath — &quot;Leg 2 · Anna Berg&quot; — and that leg&#39;s own time once it&#39;s home. Placings and gaps are between teams, and a relay class in the <strong>Classes</strong> panel counts its teams.</p><p><img src="'+o+'" alt="The commentary feed part-way through a relay. At the top, a changeover card for Kalevan Rasti 1 in H21 — &quot;Leg 2 · Juho Lehtinen · 28:30&quot;, &quot;Hands over to Aleksi Rautio at 60:40&quot;, running 2nd of 3 — with &quot;Gained 1 place&quot; and &quot;Fastest leg 2 so far&quot; chips and, on the right, the Finnish flag, the club Kalevan Rasti and bib 3.2. Below it a radio punch for IFK Göteborg 1&#39;s second leg, more changeovers, a finish and radio punches from the individual class M21E, and at the bottom the H21 mass start: &quot;Mass start at 10:30:00 — 3 teams away&quot;."></p><p>A relay produces some items an individual race doesn&#39;t:</p><ul><li><strong>Mass start</strong> — one item per class when it goes, saying how many teams went. Classes sent off at the same moment share one item.</li><li><strong>Restart</strong> — when a class restart sends waiting runners out, one item says how many went.</li><li><strong>Changeover</strong> — a leg is home and hands over: to whom, the team&#39;s time at the handover, and where the team stands. If the next runner had already gone out — at the restart, or by punching out on their own — or nobody is entered on the next leg, the item says so.</li><li><strong>Finish</strong> — the team is home with a result, with the same placing wording as an individual finish. It names the leg that brought the team home: usually the last one, but after a restart, whichever leg got back last.</li><li><strong>Class Complete</strong> — lists the teams, and under each team its runners in leg order, each with their own leg time.</li></ul><p><img src="'+r+'" alt="A Class Complete tile for H21 listing the top 3 teams with medals — Kalevan Rasti 1 in 1:29:05, Kristiansand OK 1 35 seconds behind, IFK Göteborg 1 2:07 behind — each with its three runners and their leg times beneath the team&#39;s name. Under the tile, the three teams&#39; finish cards, each naming the last leg and runner, with the team&#39;s flag, club and bib; Kalevan Rasti 1&#39;s card says it wins the class by 35s and carries &quot;Fastest leg 3 so far&quot;."></p><p>When a leg mis-punches or doesn&#39;t finish, a <strong>status</strong> item says so and names the leg. A ruling on the whole team, such as a disqualification, names no leg. The team keeps appearing after that — its radio punches and changeovers carry its status chip, so it never reads as still racing for a place — until its last runner is home.</p><p>An <strong>unofficial</strong> team (a composite team, for example) is announced as finishing with no placing, and never takes a place, a lead or a medal from an official team.</p><p>A changeover, or the item for the leg that brings a team home, can carry a <strong>Fastest leg N so far</strong> badge — or <strong>Joint fastest leg N so far</strong> when another team ran it in the same time. It compares only teams in the same class. A mis-punched leg doesn&#39;t count, and there&#39;s no badge until another team has run that leg cleanly, because until then there&#39;s nobody to compare with.</p><p>Mass starts and restarts follow the <strong>Starts</strong> switch, and changeovers have their own <strong>Changeovers</strong> switch. Individual classes at a relay event are covered exactly as at an individual event.</p><h2 id="narrowing-the-feed" tabindex="-1">Narrowing the feed <a class="header-anchor" href="#narrowing-the-feed" aria-label="Permalink to &quot;Narrowing the feed&quot;">​</a></h2><p>The panels either side of the main feed are for finding your way around it.</p><p><strong>Classes</strong> (left) lists every class with a live status at a glance:</p><ul><li>a <strong>pin</strong> to keep a class at the top — pinning also adds the class to <strong>Classes to follow closely</strong>, so smart filtering scores it higher,</li><li>⚡ for a class with <strong>recent activity</strong>,</li><li><strong>✓ Done</strong> when everyone&#39;s finished, or an <strong>X/Y</strong> finished-of-total count,</li><li>a green count when the <strong>top 10 places are decided</strong>.</li></ul><p>Click a class name to bring up its full results in a pop-over without leaving the feed.</p><h3 id="the-right-hand-panel-is-the-whole-feed" tabindex="-1">The right-hand panel is the whole feed <a class="header-anchor" href="#the-right-hand-panel-is-the-whole-feed" aria-label="Permalink to &quot;The right-hand panel is the whole feed&quot;">​</a></h3><p>The panel on the right lists <strong>every item</strong>, one line each — name, class, and the value that matters (a placing, a status, a control number). The filters never hide anything from it, whatever they are set to. Items that are <strong>also on the main feed</strong> carry a faint background, so you can see at a glance what the filters are letting through and what they are holding back.</p><p><strong>Search</strong> at the top of the panel narrows it — by name, by class, or by a control code typed as a number. It narrows the panel only; the main feed is unaffected, and it works in both Smart and Manual mode.</p><p>Click any line to open it out and read the full wording and the placing context. Click a class name on a line to bring up that class.</p><h3 id="choosing-what-reaches-the-main-feed" tabindex="-1">Choosing what reaches the main feed <a class="header-anchor" href="#choosing-what-reaches-the-main-feed" aria-label="Permalink to &quot;Choosing what reaches the main feed&quot;">​</a></h3><p>The <strong>cog</strong> in the panel header opens <strong>Commentary settings</strong>, which has two tabs: <strong>Filter</strong>, which decides which items reach the main feed, and <strong>Settings</strong>, which decides what each one says about the runner it names.</p><p>On the <strong>Filter</strong> tab, the two buttons at the top — <strong>Smart</strong> and <strong>Manual</strong> — choose between two ways of deciding what the main feed shows. Neither is &quot;off&quot;: manual filtering is a choice, not the absence of one.</p><p><strong>Smart filter (on by default)</strong> scores every item and shows you about one every few seconds, picking the most interesting one waiting. Set:</p><ul><li><strong>Show one item every</strong> — pick a rate, from one second to one a minute. Five seconds is the default.</li><li><strong>Classes to follow closely</strong> — these score higher, so their items win slots more often. Pinning a class in the <strong>Classes</strong> panel adds it here, and removing it here unpins it: they are one list.</li><li><strong>Priorities</strong> — how much each kind of thing is worth. A class finishing, somebody taking the lead, a podium place, a radio punch, and so on. At a relay event there are rows of their own for where a <strong>team</strong> stands — on the course, and home — and they are weighted higher than an individual race&#39;s: a relay goes off on a mass start, so the order on the course <em>is</em> the race. By default the leading team&#39;s changeover, the first team home and a podium team, once its place is settled, go straight to the main feed. A relay item also counts the ranking of the runner it names.</li><li><strong>Take the next slot above</strong> — a score high enough to beat everything else waiting. It takes the next slot rather than jumping the clock: the rate you set is a ceiling on everything.</li></ul><p><strong>In manual mode</strong> you choose directly:</p><ul><li><strong>Classes</strong> — limit to selected classes.</li><li><strong>Item Types</strong> — toggle <strong>Starts</strong>, <strong>Radio controls</strong> (and pick which controls), <strong>Changeovers</strong> (at a relay event), <strong>Finishes</strong> (with a <strong>Placegetters only</strong> option to show just podium finishes), and <strong>Class completions</strong>.</li></ul><p>Either way, the right-hand panel still shows everything — so if you think the feed has swallowed something, that is the one place to look.</p><h3 id="showing-who-the-runner-is" tabindex="-1">Showing who the runner is <a class="header-anchor" href="#showing-who-the-runner-is" aria-label="Permalink to &quot;Showing who the runner is&quot;">​</a></h3><p>The <strong>Settings</strong> tab adds who the runner is to the top right of each item in the main feed, beside their name and what just happened. Four switches, all off to begin with:</p><ul><li><strong>Show country flag</strong> — the flag of the runner&#39;s club&#39;s country.</li><li><strong>Show club logo</strong> — the club&#39;s badge, if one has been uploaded for it (Settings → Clubs).</li><li><strong>Show club name</strong></li><li><strong>Show bib</strong></li></ul><p>On a relay item these describe the <strong>team</strong>: its club, its club&#39;s badge and its country — a team of runners from several clubs shows the team&#39;s own. The bib is the runner&#39;s when the item names one, and the team&#39;s when it doesn&#39;t. The team&#39;s name needs no switch: a relay item is headed by it.</p><p>Switch on only what you need — each one takes a little width from the item&#39;s own sentence. A runner with no club or bib shows nothing rather than a blank line. These are a property of the screen you are sitting at — they stay when you reload it, and they do not follow you to another machine. They never change the right-hand panel, which stays one line an item.</p><h2 id="tips-for-live-commentary" tabindex="-1">Tips for live commentary <a class="header-anchor" href="#tips-for-live-commentary" aria-label="Permalink to &quot;Tips for live commentary&quot;">​</a></h2><ul><li><strong>Keep it on a dedicated screen.</strong> Open it full-screen on a second monitor and let it run; it updates itself.</li><li><strong>Pin the classes you&#39;re following</strong> so the ones that matter stay at the top as the field thins out.</li><li><strong>Use it alongside the live views.</strong> Commentary gives you the running story; pair it with <a href="./../running-the-event/tracking">Tracking</a> and <a href="./../running-the-event/live-view">Live view</a> for the spatial picture of who&#39;s where on the course.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../running-the-event/tracking">Tracking</a> — follow competitors&#39; progress around the course</li><li><a href="./../running-the-event/live-view">Live view</a> — the live state of the event</li><li><a href="./creating-screens">Creating screens</a> — the arena displays, and choosing what each one shows</li></ul>',44)])])}const f=t(i,[["render",h]]);export{p as __pageData,f as default};
